정선에서 초·중·고등학교를 졸업한 그는 현재 아주대학교 공공정책대학원 행정학과 석사과정에 재학 중이다. 최 예비후보는 기자 출신으로, 더불어민주당 강원특별자치도당 체육특별위원회 부위원장, 정선초등학교 운영위원장, 전 한국지역신문협회 강원협의회 사무국장, 정선교육지원청 교육환경심의위원, 정선군의회 윤리자문심사위원 등을 지냈다. 그는 ▲농어촌 기본소득 사업의 항구화 ▲강원랜드 NEW K-HIT 프로젝트의 지역 상생 유도 ▲지역 자생 경제 환경 구축 ▲단열 리모델링 지원을 통한 '난방복지도시' 구축 ▲정선군 닥터헬기 단독 운용 추진 등을 목표로 내걸었다. 최 예비후보는 "지역 언론인으로서 현장을 발로 뛰며 정책의 문제점과 대안을 꾸준히 제시해왔다"며 "그동안의 취재 경험과 정책 분석 역량을 바탕으로, 도의회에서 실질적인 예산 확보와 제도 개선을 이끌겠다"고 말했다. 이어 "지역언론을 통해 감시하고 기록해 온 역할에서 이제는 직접 실행하는 자리에서 실천하겠다"며 "군민의 삶을 바꾸는 '결과 중심의 의정활동'으로 보답하겠다"고 했다. 기사이력코드 취재(자료보완) 취재(기획) 취재(제보) 취재(자료보완) 보도자료 SNS 서핑 기타(국내외 논문·학술지) 기타(증권사 리포트) 기타(타 언론사 후속보도) 메트로신문 김보민 인턴기자 kbm@metroseoul.co.kr 다른기사 보기 Copyright ⓒ 메트로신문 & metroseoul.co.kr function goSearchPage(searchText){ location.href="/search?searchText="+encodeURI(searchText); return; } (function () { $.ajax({ type : "GET", url : "/wps/engine/rest/35?type=COMPONENT", success: function (data) { $("#ZxBejhqxJS").after(data); $("#ZxBejhqxJS").remove(); } }); })() 메트로신문 지면 PDF 보기 // 현재 날짜 구하기 var now = new Date(); // 요일 체크 (0 = 일요일, 1 = 월요일, ..., 6 = 토요일) var dayName = now.getDay(); // 주말이면 금요일 날짜로 바꾸기 if (dayName === 0) { // 일요일이면 now.setDate(now.getDate() - 2); // 금요일로 이동 } else if (dayName === 6) { // 토요일이면 now.setDate(now.getDate() - 1); // 금요일로 이동 } // MMddDate: MMDD 형식 var MMddDate = ("0" + (now.getMonth() + 1)).slice(-2) + ("0" + now.getDate()).slice(-2); // yyyyMMddDate: yyyy/MM/dd 형식 var yyyyMMddDate = now.getFullYear() + "/" + ("0" + (now.getMonth() + 1)).slice(-2) + "/" + ("0" + now.getDate()).slice(-2); // yyyyMMddDate2: yyyy-MM-dd 형식 var yyyyMMddDate2 = now.getFullYear() + "-" + ("0" + (now.getMonth() + 1)).slice(-2) + "-" + ("0" + now.getDate()).slice(-2); // 이미지 src URL 생성 var imageUrl = "https://pdf.metroseoul.co.kr/pdf/" + yyyyMMddDate + "/img/s10/kr_metro_1_" + MMddDate + "_01.jpg"; // HTML 요소에 값 삽입 document.getElementById('pdfImage').setAttribute('src', imageUrl); document.getElementById('pdfDate').textContent = yyyyMMddDate2; (function () { $.aj